    <div class="wrap" part="base">
      <video part="video" class="video" playsinline></video>
      <slot></slot>
      <div class="scrim" aria-hidden="true"></div>
      <iswc-button part="big-play" class="big-play" variant="text" color="text" aria-label="Reproducir">
        <iswc-icon icon="mdi:play" aria-hidden="true"></iswc-icon>
      </iswc-button>
      <div part="controls" class="controls" hidden>
        <div part="progress" class="progress">
          <input part="seek" class="seek" type="range" min="0" max="1000" value="0" step="1" aria-label="Posici\xF3n" />
          <div class="bar" aria-hidden="true">
            <div class="buffered"></div>
            <div class="played"></div>
          </div>
          <span class="thumb" aria-hidden="true"></span>
          <span class="tip" aria-hidden="true">0:00</span>
        </div>
        <div class="row">
          <iswc-check-icon-button
            part="play-button"
            class="ctrl play"
            variant="plain"
            icon="mdi:play"
            checked-icon="mdi:pause"
            label="Reproducir"
            checked-label="Pausar"
          ></iswc-check-icon-button>
          <div part="volume" class="vol">
            <iswc-check-icon-button
              part="mute-button"
              class="ctrl mute"
              variant="plain"
              icon="mdi:volume-high"
              checked-icon="mdi:volume-off"
              label="Silenciar"
              checked-label="Activar sonido"
            ></iswc-check-icon-button>
            <input
              part="volume-slider"
              class="volume"
              type="range"
              min="0"
              max="100"
              value="100"
              aria-label="Volumen"
            />
          </div>
          <span part="time" class="time">
            <span class="cur">0:00</span><span class="sep">/</span><span class="dur">0:00</span>
          </span>
          <span class="spacer"></span>
          <div class="settings">
            <iswc-button part="settings-button" class="iconbtn speed" variant="text" color="text"
                    aria-label="Velocidad de reproducci\xF3n" aria-haspopup="true" aria-expanded="false">
              <iswc-icon icon="mdi:cog-outline" aria-hidden="true"></iswc-icon>
            </iswc-button>
            <ul class="menu" role="menu" hidden>
              <li class="menu__head" role="presentation">Velocidad</li>
            </ul>
          </div>
          <iswc-check-icon-button
            part="pip-button"
            class="ctrl pip"
            variant="plain"
            icon="mdi:picture-in-picture-bottom-right"
            checked-icon="mdi:picture-in-picture-top-right"
            label="Picture in picture"
            checked-label="Salir de picture in picture"
            hidden
          ></iswc-check-icon-button>
          <iswc-check-icon-button
            part="fullscreen-button"
            class="ctrl fs"
            variant="plain"
            icon="mdi:fullscreen"
            checked-icon="mdi:fullscreen-exit"
            label="Pantalla completa"
            checked-label="Salir de pantalla completa"
          ></iswc-check-icon-button>
        </div>
      </div>
    </div>
